export function computeTotal(cart) {
  let total = 0;
  for (const item of cart.items) {
    total += priceOf(item);
  }
  return total;
}
function priceOf(item) {
  if (item.sku === 'broken') {
    throw new TypeError(`Cannot read price of ${item.sku}`);
  }
  return item.price * item.qty;
}
export function runCheckout() {
  return computeTotal({ items: [{ sku: 'a', price: 2, qty: 1 }, { sku: 'broken' }] });
}
